database_schema:
CREATE TABLE users (id UUID PRIMARY KEY, username VARCHAR(150) UNIQUE, password_hash VARCHAR(255), created_at TIMESTAMP);
CREATE TABLE accounts (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), balance NUMERIC(15,2), currency VARCHAR(3), updated_at TIMESTAMP);
CREATE TABLE transactions (id UUID PRIMARY KEY, account_id UUID REFERENCES accounts(id), type VARCHAR(50), amount NUMERIC(15,2), description TEXT, created_at TIMESTAMP);
CREATE TABLE bill_payments (id UUID PRIMARY KEY, account_id UUID REFERENCES accounts(id), biller_id VARCHAR(100), amount NUMERIC(15,2), reference_number VARCHAR(100), status VARCHAR(20), paid_at TIMESTAMP);
